window.CODE_LIBRARY = {"lessons": [{"number": 1, "title": "\u7b2c1\u56de", "codes": [{"name": "\u306f\u3058\u3081\u3066\u306e\u51fa\u529b", "filename": "01_\u306f\u3058\u3081\u3066\u306e\u51fa\u529b.py", "content": "# \u6587\u5b57\u3092\u753b\u9762\u306b\u8868\u793a\u3057\u3066\u307f\u3088\u3046\nprint(\"\u3053\u3093\u306b\u3061\u306f\u3001\u30d7\u30ed\u30b0\u30e9\u30df\u30f3\u30b0\uff01\")\nprint(\"\u81ea\u5206\u306e\u540d\u524d\u306b\u5909\u3048\u3066\u307f\u3088\u3046\")\n"}, {"name": "\u5909\u6570\u3092\u4f7f\u3063\u3066\u307f\u3088\u3046", "filename": "02_\u5909\u6570\u3092\u4f7f\u3063\u3066\u307f\u3088\u3046.py", "content": "name = \"\u9ad8\u6821\u751f\"\nage = 16\nprint(f\"\u3053\u3093\u306b\u3061\u306f\u3001{name}\u3055\u3093\uff01\")\nprint(f\"\u6765\u5e74\u306f{age + 1}\u6b73\u3067\u3059\u306d\u3002\")\n"}]}, {"number": 2, "title": "\u7b2c2\u56de", "codes": [{"name": "\u6761\u4ef6\u5206\u5c90", "filename": "01_\u6761\u4ef6\u5206\u5c90.py", "content": "# \u6570\u5b57\u3092\u5909\u3048\u3066\u7d50\u679c\u3092\u78ba\u304b\u3081\u3088\u3046\nscore = 75\nif score >= 80:\n    print(\"\u3059\u3070\u3089\u3057\u3044\uff01\")\nelif score >= 60:\n    print(\"\u3088\u304f\u3067\u304d\u307e\u3057\u305f\uff01\")\nelse:\n    print(\"\u3082\u3046\u4e00\u5ea6\u30c1\u30e3\u30ec\u30f3\u30b8\uff01\")\n"}]}, {"number": 3, "title": "\u7b2c3\u56de", "codes": [{"name": "\u7e70\u308a\u8fd4\u3057", "filename": "01_\u7e70\u308a\u8fd4\u3057.py", "content": "for number in range(1, 6):\n    print(f\"{number}\u56de\u76ee\u306e\u3053\u3093\u306b\u3061\u306f\uff01\")\nprint(\"\u7e70\u308a\u8fd4\u3057\u304c\u7d42\u308f\u308a\u307e\u3057\u305f\u3002\")\n"}]}, {"number": 4, "title": "\u7b2c4\u56de", "codes": [{"name": "\u30ea\u30b9\u30c8", "filename": "01_\u30ea\u30b9\u30c8.py", "content": "fruits = [\"\u308a\u3093\u3054\", \"\u307f\u304b\u3093\", \"\u3076\u3069\u3046\"]\nfruits.append(\"\u3044\u3061\u3054\")\nfor fruit in fruits:\n    print(f\"\u597d\u304d\u306a\u679c\u7269\uff1a{fruit}\")\n"}]}, {"number": 5, "title": "\u7b2c5\u56de", "codes": [{"name": "\u95a2\u6570", "filename": "01_\u95a2\u6570.py", "content": "def greet(name):\n    return f\"\u3053\u3093\u306b\u3061\u306f\u3001{name}\u3055\u3093\uff01\"\n\nprint(greet(\"\u592a\u90ce\"))\nprint(greet(\"\u82b1\u5b50\"))\n"}]}, {"number": 6, "title": "\u7b2c6\u56de", "codes": [{"name": "\u3058\u3083\u3093\u3051\u3093\u30b2\u30fc\u30e0", "filename": "01_\u3058\u3083\u3093\u3051\u3093\u30b2\u30fc\u30e0.py", "content": "import random\n\nhands = [\"\u30b0\u30fc\", \"\u30c1\u30e7\u30ad\", \"\u30d1\u30fc\"]\nplayer = input(\"\u30b0\u30fc\u30fb\u30c1\u30e7\u30ad\u30fb\u30d1\u30fc\u306e\u3069\u308c\u304b\u3092\u5165\u529b\u3057\u3066\u304f\u3060\u3055\u3044\uff1a\").strip()\nif player not in hands:\n    print(\"\u30b0\u30fc\u30fb\u30c1\u30e7\u30ad\u30fb\u30d1\u30fc\u306e\u3069\u308c\u304b\u3067\u3001\u3082\u3046\u4e00\u5ea6\u5b9f\u884c\u3057\u3066\u306d\u3002\")\nelse:\n    computer = random.choice(hands)\n    print(f\"\u30b3\u30f3\u30d4\u30e5\u30fc\u30bf\u30fc\uff1a{computer}\")\n    if player == computer:\n        print(\"\u3042\u3044\u3053\uff01\")\n    elif (hands.index(player) - hands.index(computer)) % 3 == 2:\n        print(\"\u3042\u306a\u305f\u306e\u52dd\u3061\uff01\")\n    else:\n        print(\"\u30b3\u30f3\u30d4\u30e5\u30fc\u30bf\u30fc\u306e\u52dd\u3061\uff01\")\n"}]}]};
